import React from "react";
import { Link } from "react-router-dom";
import { useApp } from "../lib/AppContext";
import StatCard from "../components/ui/StatCard";
import LiveReportMap from "../components/dashboard/LiveReportMap";
import LiveQueueFeed from "../components/dashboard/LiveQueueFeed";
import {
  CategoryChart,
  ResolutionChart,
} from "../components/dashboard/AnalyticsCharts";
const Dashboard = () => {
  const { reports } = useApp();
  const pending = reports.filter((report) =>
    ["SUBMITTED", "UNDER_REVIEW"].includes(report.status),
  ).length;
  const inProgress = reports.filter(
    (report) => report.status === "IN_PROGRESS",
  ).length;
  const resolved = reports.filter(
    (report) => report.status === "RESOLVED",
  ).length;
  return (
    <>
      <div className="mb-6 flex flex-wrap items-center justify-between gap-3">
        <div>
          <div className="text-[9px] font-bold tracking-widest text-gray-400">
            THURSDAY, OCTOBER 8, 2026
          </div>
          <h1 className="my-2 font-['Manrope',sans-serif] text-2xl font-bold tracking-tight text-[#17251d]">
            Good morning, Thoko <span>✳</span>
          </h1>
          <p className="text-[11px] text-gray-500">
            Here’s what’s happening across your region today.
          </p>
        </div>
        <Link
          className="rounded-lg bg-[#185835] px-4 py-3 text-[11px] font-semibold text-white shadow-sm hover:bg-[#12472a]"
          to="/reports"
        >
          View reports queue <span>→</span>
        </Link>
      </div>
      <div className="mb-4 grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
        <StatCard
          title="Total reports"
          value={String(reports.length).padStart(2, "0")}
          change="↑ 12%"
          note="vs. last month"
          icon="▤"
          tone="green"
        />
        <StatCard
          title="Pending review"
          value={String(pending).padStart(2, "0")}
          change="Needs attention"
          note="Review new cases"
          icon="◷"
          tone="amber"
        />
        <StatCard
          title="In progress"
          value={String(inProgress).padStart(2, "0")}
          change="Active cases"
          note="Across your region"
          icon="↗"
          tone="blue"
        />
        <StatCard
          title="Resolved cases"
          value={String(resolved).padStart(2, "0")}
          change="↑ 8%"
          note="vs. last month"
          icon="✓"
          tone="mint"
        />
      </div>
      <div className="mb-4 grid gap-4 xl:grid-cols-[1.5fr_1fr]">
        <LiveReportMap reports={reports} />
        <LiveQueueFeed reports={reports} />
      </div>
      <div className="grid gap-4 xl:grid-cols-2">
        <ResolutionChart />
        <CategoryChart />
      </div>
    </>
  );
};
export default Dashboard;
